            decorated.sort((a,b)=>b.lum-a.lum||a.index-b.index);markPlaylistPaletteEdited(r);r.keyColors=decorated.map(x=>x.color);playlistPaletteSelectedIndex.set(key,Math.max(0,decorated.findIndex(x=>x.selected)));renderPlaylistPaletteStudio();schedulePlaylistPaletteRuntimeRefresh(key);
