                    const addRight=document.createElement('button');addRight.type='button';addRight.textContent='＋ справа';addRight.title='Добавить цвет справа от выбранного';addRight.addEventListener('click',()=>insertPlaylistPaletteKeyColor(key,'right'));
                    const sort=document.createElement('button');sort.type='button';sort.textContent='☀ яркость';sort.title='Выстроить ключевые цвета от самого яркого к самому тёмному';sort.addEventListener('click',()=>sortPlaylistPaletteByBrightness(key));
                    actions.append(rem,addLeft,addRight,sort);editor.appendChild(actions);
