                    const total=document.createElement('div');total.className='palette-total-text';total.textContent=`Итого цветов: ${playlistPaletteTotalCount(record)} · ключевых: ${record.keyColors.length} · основной: 1-й слева`;editor.appendChild(total);
                    editor.appendChild(makeControl('Насыщенность',0,200,record.saturation,v=>{record.saturation=Math.max(0,Math.min(200,v));schedulePlaylistPaletteRuntimeRefresh(key);}));
