            palettes[key]={id:key,name:`Новая палитра ${Object.keys(palettes).filter(k=>!PLAYLIST_PALETTE_ORDER.includes(k)).length+1}`,keyColors:['#22d3ee','#f472b6'],multiplier:1,saturation:100,brightness:50,contrast:50,active:true,factoryKey:null,exactColors:null};playlistPaletteSelectedIndex.set(key,0);playlistPaletteExpandedKey=key;renderPlaylistPaletteButtons();renderPlaylistPaletteStudio();renderPaletteQuickMenu();
