        function syncRandomSettingsUI() {
            const values = {
                randomByShape: state.randomOptions.byShape,
                randomOnlyLine: state.randomOptions.onlyLine,
                randomByVertices: state.randomOptions.byVertices,
                randomBySteps: state.randomOptions.bySteps,
                randomByRounding: state.randomOptions.byRounding,
                randomBySize: state.randomOptions.bySize,
                randomByColor: state.randomOptions.byColor,
                randomBySpiralLayers: state.randomOptions.bySpiralLayers !== false
            };
            Object.entries(values).forEach(([id, value]) => {
                const el = document.getElementById(id);
                if (el) el.checked = Boolean(value);
            });
            const count = document.getElementById('randomLayerCount');
            if (count) count.value = state.randomLayerCount;
            const randomSpiralMin = document.getElementById('randomSpiralLayersMin');
            const randomSpiralMax = document.getElementById('randomSpiralLayersMax');
            if (randomSpiralMin) randomSpiralMin.value = Math.max(0, Math.round(Number(state.randomOptions.spiralLayersMin) || 0));
            if (randomSpiralMax) randomSpiralMax.value = Math.max(0, Math.round(Number(state.randomOptions.spiralLayersMax ?? 1) || 0));
            const rc=document.getElementById('randomCyclePalettes');if(rc)rc.checked=state.randomOptions?.cyclePalettes===true;
            const minimalInterval = document.getElementById('minimalMorphInterval');
            const minimalFade = document.getElementById('minimalMorphFade');
            const minimalInstant = document.getElementById('minimalMorphInstant');
            const minimalDefaultActive = document.getElementById('minimalMorphDefaultActive');
            const minimalFadeRow = document.getElementById('minimalMorphFadeRow');
            if (minimalInterval) minimalInterval.value = formatDisplayNumber(isTapMorphSyncActive('minimal') ? getTapTempoIntervalSec(state.minimalMorph?.intervalSec ?? 5) : (state.minimalMorph?.intervalSec ?? 5), 2);
            if (minimalFade) minimalFade.value = formatDisplayNumber(state.minimalMorph?.fadeSec ?? 0.1, 1);
            if (minimalInstant) minimalInstant.checked = state.minimalMorph?.instantSwitch !== false;
            if (minimalDefaultActive) minimalDefaultActive.checked = state.minimalMorph?.defaultActive === true;
            if (minimalFade) minimalFade.disabled = state.minimalMorph?.instantSwitch !== false;
            minimalFadeRow?.classList.toggle('shape-disabled', state.minimalMorph?.instantSwitch !== false);
            syncPlaylistPaletteSelectionUI();
            syncTapTimingIndicators();
        }

        function updateMorphShapeControlsEnabled() {
            const row = document.getElementById('morphShapeRow');
            const enabled = document.getElementById('morphByShape')?.checked !== false;
            row?.classList.toggle('shape-disabled', !enabled);
        }

        function normalizedMorphShapeSelections() {
            const shape = state.morph.shapeOptions || (state.morph.shapeOptions = {});
            // Keep legacy topology flags readable for old project files and the
            // procedural fallback. The visible v96 UI is driven by profileGroups.
            let noLoops = typeof shape.noLoops === 'boolean' ? shape.noLoops : shape.loops !== true;
            let loops = typeof shape.loops === 'boolean' ? shape.loops : false;
            let closed = typeof shape.closed === 'boolean' ? shape.closed : shape.open !== true;
            let open = typeof shape.open === 'boolean' ? shape.open : false;
            shape.noLoops = noLoops;
            shape.loops = loops;
            shape.closed = closed;
            shape.open = open;
            return { noLoops, loops, closed, open };
        }

        function normalizedMorphProfileGroups() {
            const shape = state.morph.shapeOptions || (state.morph.shapeOptions = {});
            let groups = Array.isArray(shape.profileGroups)
                ? shape.profileGroups.map(group => group === 'noLoops' ? 'closed' : group).filter(group => MORPH_PROFILE_GROUP_KEYS.includes(group))
                : [];
            groups = [...new Set(groups)];

            // Backward compatibility: the removed "noLoops" folder maps to the new
            // merged "closed" folder.
            if (!groups.length) {
                const legacyRaw = shape.profileGroup;
                const legacy = legacyRaw === 'noLoops' ? 'closed' : legacyRaw;
                if (MORPH_PROFILE_GROUP_KEYS.includes(legacy)) groups = [legacy];
                else if (shape.standardOnly === true) groups = ['standard'];
                else groups = ['standard','closed'];
            }
            if (!groups.length) groups = ['standard'];

            shape.profileGroups = groups.slice();
            // Keep legacy fields coherent so old saved settings remain readable.
            shape.profileGroup = groups.length === 1 ? groups[0] : 'all';
            shape.standardOnly = groups.length === 1 && groups[0] === 'standard';
            return groups;
        }

        function syncMorphShapeToggleButtons() {
            const groups = normalizedMorphProfileGroups();
            document.querySelectorAll('[data-morph-profile-group]').forEach(control => {
                const on = groups.includes(control.dataset.morphProfileGroup);
                if (control instanceof HTMLInputElement && control.type === 'checkbox') control.checked = on;
                else {
                    control.classList.toggle('active', on);
                    control.setAttribute('aria-pressed', on ? 'true' : 'false');
                }
            });
        }

