            if (interval && document.activeElement !== interval) interval.value = formatDisplayNumber(pm.intervalSec, 2);
            const syncTap = document.getElementById('projectMorphSyncTap'); if (syncTap) syncTap.checked = pm.syncTap !== false;
            const beats = document.getElementById('projectMorphBeats'); if (beats && document.activeElement !== beats) beats.value = String(pm.beatsPerProject);
            const transitionBeats = document.getElementById('projectMorphTransitionBeats'); if (transitionBeats && document.activeElement !== transitionBeats) transitionBeats.value = String(pm.transitionBeats);
            const cameraWander = document.getElementById('projectMorphCameraWander'); if (cameraWander) cameraWander.checked = pm.cameraWander === true;
            const transitionType = document.getElementById('projectMorphTransitionType'); if (transitionType) transitionType.value = pm.transitionType;
            const advancedLinear = document.getElementById('projectMorphAdvancedLinear'); if (advancedLinear) advancedLinear.checked = pm.advancedLinear === true;
            document.getElementById('projectMorphAdvancedLinearRow')?.classList.toggle('hidden',pm.transitionType!=='linear');
            const transitionSec = document.getElementById('projectMorphTransitionSec');
            if (transitionSec && document.activeElement !== transitionSec) transitionSec.value = formatDisplayNumber(pm.transitionSec, 2);
            const imageTransition = document.getElementById('projectMorphImageTransitionType'); if (imageTransition) imageTransition.value = pm.imageTransitionType;
            const centerSoft = document.getElementById('projectMorphCenterSoftness'); if (centerSoft && document.activeElement !== centerSoft) centerSoft.value = String(pm.imageCenterSoftness);
            const sectorSoft = document.getElementById('projectMorphSectorSoftness'); if (sectorSoft && document.activeElement !== sectorSoft) sectorSoft.value = String(pm.imageSectorSoftness);
            const centerSoftValue = document.getElementById('projectMorphCenterSoftnessValue'); if (centerSoftValue) centerSoftValue.textContent = `${Math.round(pm.imageCenterSoftness)}%`;
            const sectorSoftValue = document.getElementById('projectMorphSectorSoftnessValue'); if (sectorSoftValue) sectorSoftValue.textContent = `${Math.round(pm.imageSectorSoftness)}%`;
