            state.morph.stepMin = Number.isFinite(Number(m.stepMin)) ? Number(m.stepMin) : state.morph.stepMin;
            state.morph.stepMax = Number.isFinite(Number(m.stepMax)) ? Number(m.stepMax) : state.morph.stepMax;
            if (typeof m.monoOrbitTransforms === 'boolean') state.morph.monoOrbitTransforms = m.monoOrbitTransforms;
            state.morph.orbitPercentMin = Number.isFinite(Number(m.orbitPercentMin)) ? Math.round(Math.max(0, Math.min(100, Number(m.orbitPercentMin)))) : state.morph.orbitPercentMin;
            state.morph.orbitPercentMax = Number.isFinite(Number(m.orbitPercentMax)) ? Math.round(Math.max(state.morph.orbitPercentMin, Math.min(100, Number(m.orbitPercentMax)))) : state.morph.orbitPercentMax;
            state.morph.strokeWidthMin = Number.isFinite(Number(m.strokeWidthMin)) ? Math.max(0.5, Math.min(20, Number(m.strokeWidthMin))) : state.morph.strokeWidthMin;
            state.morph.strokeWidthMax = Number.isFinite(Number(m.strokeWidthMax)) ? Math.max(state.morph.strokeWidthMin, Math.min(20, Number(m.strokeWidthMax))) : state.morph.strokeWidthMax;
            state.morph.opacityMin = Number.isFinite(Number(m.opacityMin)) ? Math.round(Math.max(0, Math.min(100, Number(m.opacityMin)))) : state.morph.opacityMin;
            state.morph.opacityMax = Number.isFinite(Number(m.opacityMax)) ? Math.round(Math.max(state.morph.opacityMin, Math.min(100, Number(m.opacityMax)))) : state.morph.opacityMax;
            state.morph.fillLayersMin = Number.isFinite(Number(m.fillLayersMin)) ? Math.max(0, Math.min(64, Math.round(Number(m.fillLayersMin)))) : state.morph.fillLayersMin;
            state.morph.fillLayersMax = Number.isFinite(Number(m.fillLayersMax)) ? Math.max(state.morph.fillLayersMin, Math.min(64, Math.round(Number(m.fillLayersMax)))) : state.morph.fillLayersMax;
            state.morph.fillHueMin = Number.isFinite(Number(m.fillHueMin)) ? Math.max(-180, Math.min(180, Math.round(Number(m.fillHueMin)))) : state.morph.fillHueMin;
            state.morph.fillHueMax = Number.isFinite(Number(m.fillHueMax)) ? Math.max(state.morph.fillHueMin, Math.min(180, Math.round(Number(m.fillHueMax)))) : state.morph.fillHueMax;
            if (typeof m.fillHueReset === 'boolean') state.morph.fillHueReset = m.fillHueReset;
            if (typeof m.fillHueHarmony === 'string' && PROJECT_FILL_HARMONY_KEYS.has(m.fillHueHarmony)) state.morph.fillHueHarmony = m.fillHueHarmony;
            else if (typeof m.fillHueReset === 'boolean') state.morph.fillHueHarmony = m.fillHueReset ? 'native' : 'all';
            if (Number.isFinite(Number(m.sizeVariation))) state.morph.sizeVariation = Math.round(Math.max(0, Math.min(100, Number(m.sizeVariation))));
            state.morph.sizeVariationMultiplier = Number.isFinite(Number(m.sizeVariationMultiplier)) ? Math.max(0, Number(m.sizeVariationMultiplier)) : (Number.isFinite(Number(m.sizeVariation)) ? 1 : state.morph.sizeVariationMultiplier);
            
            if (typeof m.normalizeSizes === 'boolean') state.morph.normalizeSizes = m.normalizeSizes;
            state.morph.rotationMinPercent = Number.isFinite(Number(m.rotationMinPercent)) ? Math.round(Math.max(0, Math.min(100, Number(m.rotationMinPercent)))) : state.morph.rotationMinPercent;
            state.morph.rotationMaxPercent = Number.isFinite(Number(m.rotationMaxPercent)) ? Math.round(Math.max(state.morph.rotationMinPercent, Math.min(100, Number(m.rotationMaxPercent)))) : state.morph.rotationMaxPercent;
            state.morph.rotationMultiplier = Number.isFinite(Number(m.rotationMultiplier)) ? Math.max(0, Number(m.rotationMultiplier)) : state.morph.rotationMultiplier;
            if (typeof m.rotationRandomDirection === 'boolean') state.morph.rotationRandomDirection = m.rotationRandomDirection;
            state.morph.fillOpacityMin = Number.isFinite(Number(m.fillOpacityMin)) ? Math.round(Math.max(0, Math.min(100, Number(m.fillOpacityMin)))) : state.morph.fillOpacityMin;
            state.morph.fillOpacityMax = Number.isFinite(Number(m.fillOpacityMax)) ? Math.round(Math.max(state.morph.fillOpacityMin, Math.min(100, Number(m.fillOpacityMax)))) : state.morph.fillOpacityMax;
            state.morph.splinePoints = normalizeSplinePointCount(m.splinePoints ?? state.morph.splinePoints ?? 12);
            state.morph.spiralOrderMin = normalizeSpiralOrder(m.spiralOrderMin ?? state.morph.spiralOrderMin ?? -1, true);
            state.morph.spiralOrderMax = normalizeSpiralOrder(m.spiralOrderMax ?? state.morph.spiralOrderMax ?? 1, true);
            if (state.morph.spiralOrderMin > state.morph.spiralOrderMax) [state.morph.spiralOrderMin,state.morph.spiralOrderMax]=[state.morph.spiralOrderMax,state.morph.spiralOrderMin];
            state.morph.spiralOrderLinked = m.spiralOrderLinked === true;
            state.morph.lineColorPalette = normalizePlaylistPaletteKey(m.lineColorPalette,state.morph.lineColorPalette||'standard');
            state.morph.cyclePalettes = m.cyclePalettes === true;
            state.morph.morphGlobalHueOffset = m.morphGlobalHueOffset === true;
            state.morph.globalHueOffsetRange = Number.isFinite(Number(m.globalHueOffsetRange)) ? Math.max(0,Math.min(360,Math.round(Number(m.globalHueOffsetRange)))) : (state.morph.globalHueOffsetRange ?? 180);
            state.morph.spiralLayersMin = Number.isFinite(Number(m.spiralLayersMin)) ? Math.max(0, Math.min(64, Math.round(Number(m.spiralLayersMin)))) : (state.morph.spiralLayersMin ?? 0);
            state.morph.spiralLayersMax = Number.isFinite(Number(m.spiralLayersMax)) ? Math.max(state.morph.spiralLayersMin, Math.min(64, Math.round(Number(m.spiralLayersMax)))) : (state.morph.spiralLayersMax ?? 1);
            if (typeof m.chaosMorphEnabled === 'boolean') state.morph.chaosMorphEnabled = m.chaosMorphEnabled;
            state.morph.chaosMorphStepSpread = Number.isFinite(Number(m.chaosMorphStepSpread)) ? Math.max(0,Math.min(120,Math.round(Number(m.chaosMorphStepSpread)))) : (state.morph.chaosMorphStepSpread ?? 1);
            state.morph.chaosMorphClosuresMax = Number.isFinite(Number(m.chaosMorphClosuresMax)) ? Math.max(0,Math.min(120,Math.round(Number(m.chaosMorphClosuresMax)))) : (state.morph.chaosMorphClosuresMax ?? 3);
            if (typeof m.preserveSpiralContinuity === 'boolean') state.morph.preserveSpiralContinuity = m.preserveSpiralContinuity;
            state.morph.spiralMorphType=normalizeSpiralMorphType(m.spiralMorphType,state.morph.preserveSpiralContinuity!==false);
