            let hp=Math.max(0,Math.min(1000,Number(hpEl.value)||0)),lp=Math.max(0,Math.min(1000,Number(lpEl.value)||1000));if(lp<hp){if(changed==='lp')hp=lp;else lp=hp;}
            const needed=ar.bandCount-1;let edgeHz=Array.isArray(ar.masterBandEdges)?ar.masterBandEdges.slice(0,needed):[];if(!edgeHz.length&&needed)edgeHz=getDefaultMasterBandEdges(ar.bandCount);
            let edgePos=edgeHz.map(frequencyToRange);while(edgePos.length<needed)edgePos.push(frequencyToRange(getDefaultMasterBandEdges(ar.bandCount)[edgePos.length]||rangeToFrequency(lp)));
            if(changed&&changed.startsWith('cut')){const idx=Number(changed.slice(3));if(Number.isInteger(idx)&&cuts[idx])edgePos[idx]=Number(cuts[idx].value)||0;}
            edgePos=edgePos.slice(0,needed).map(v=>Math.max(hp,Math.min(lp,v))).sort((a,b)=>a-b);
            hpEl.value=String(hp);lpEl.value=String(lp);cuts.forEach((el,i)=>{if(!el)return;el.style.display=i<needed?'block':'none';if(i<needed)el.value=String(edgePos[i]??hp);});
            ar.highPassHz=rangeToFrequency(hp);ar.lowPassHz=rangeToFrequency(lp);ar.masterBandEdges=edgePos.map(rangeToFrequency);if(ar.bandCount===3){ar.lowHz=ar.masterBandEdges[0]||120;ar.highHz=ar.masterBandEdges[1]||5000;}
