        window.__spiroWindingFillProbe=()=>{
            const poly=[{x:0,y:0},{x:10,y:8},{x:0,y:8},{x:10,y:0}],anchor={x:-25,y:-25};
            const orient=(a,b,c)=>(b.x-a.x)*(c.y-a.y)-(b.y-a.y)*(c.x-a.x);
            const insideTri=(p,a,b,c)=>{
                const o=orient(a,b,c);if(Math.abs(o)<1e-10)return 0;
                const s=o>0?1:-1;
                const a1=orient(a,b,p)*s,b1=orient(b,c,p)*s,c1=orient(c,a,p)*s;
                return a1>=-1e-9&&b1>=-1e-9&&c1>=-1e-9?s:0;
            };
            const fanWinding=p=>{
                let w=0;for(let i=0;i<poly.length;i++)w+=insideTri(p,anchor,poly[i],poly[(i+1)%poly.length]);return w;
            };
            const rayWinding=p=>{
                let w=0;
                for(let i=0;i<poly.length;i++){
                    const a=poly[i],b=poly[(i+1)%poly.length];
                    if(a.y<=p.y){if(b.y>p.y&&orient(a,b,p)>0)w++;}
                    else if(b.y<=p.y&&orient(a,b,p)<0)w--;
                }
                return w;
            };
            let samples=0,mismatch=0,maxAbsDiff=0;
            for(let y=-2;y<=10;y+=.5)for(let x=-2;x<=12;x+=.5){
                const p={x,y};
                // Ignore exact edge samples where raster coverage rules, not winding algebra,
                // determine ownership.
                let edge=false;
                for(let i=0;i<poly.length;i++){const a=poly[i],b=poly[(i+1)%poly.length],cross=Math.abs(orient(a,b,p));if(cross<1e-8&&p.x>=Math.min(a.x,b.x)-1e-8&&p.x<=Math.max(a.x,b.x)+1e-8&&p.y>=Math.min(a.y,b.y)-1e-8&&p.y<=Math.max(a.y,b.y)+1e-8){edge=true;break;}}
                if(edge)continue;
                const a=fanWinding(p),b=rayWinding(p),d=Math.abs(a-b);samples++;maxAbsDiff=Math.max(maxAbsDiff,d);if(d!==0)mismatch++;
            }
            return{samples,mismatch,maxAbsDiff,pass:mismatch===0,semantic:'oriented outside-anchor edge fan equals non-zero winding number away from exact edges'};
        };

