            const start={x:100,y:0,widthScale:1,__spiralClosed:true,__spiralDelta:delta,__spiralTargetScale:scale,__spiralTangential:false,__spiralRoundSeams:true};
            const end=transformSpiralCopyPoint(start,delta,scale,1);
